with valid as (select id, order_id, method, amount, paid_at, case when amount >= 1320 then 'High' when amount >= 240 then 'Medium' else 'Low' end as amount_band from payments where paid_at >= date '2024-01-13' and order_id in (1, 29, 35)) select * from (select order_id, method, amount from valid) src pivot (avg(amount) as total, count(1) as item_count for method in ('promptpay' as promptpay, 'bank_transfer' as bank_transfer))
